 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            if len(comp) < 6:
                continue
            y0, y1 = min(y for y, _ in comp), max(y for y, _ in comp)
            x0, x1 = min(x for _, x in comp), max(x for _, x in comp)
            area = (y1-y0+1)*(x1-x0+1)
            if len(comp) / area >= 0.45:
                for y in range(y0, y1+1):
                    for x in range(x0, x1+1):
                        out[y][x] = color
    return out
